{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'threshold' not in case:
        raise ValueError("Missing 'threshold'")
    if 'calls' not in case:
        raise ValueError("Missing 'calls'")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    required_call_fields = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
    for idx, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"call at index {idx} is not a dict")
        for field in required_call_fields:
            if field not in call:
                raise ValueError(f"Missing field '{field}' in call at index {idx}")
        call_id = call['call_id']
        if not isinstance(call_id, str):
            raise ValueError(f"call_id at index {idx} must be string")
        loss_without = call['loss_without_call']
        if not isinstance(loss_without, (int, float)):
            raise ValueError(f"loss_without_call at index {idx} must be number")
        loss_with = call['loss_with_call']
        if not isinstance(loss_with, (int, float)):
            raise ValueError(f"loss_with_call at index {idx} must be number")
        tokens = call['prediction_tokens']
        if not isinstance(tokens, int) or tokens < 0:
            raise ValueError(f"prediction_tokens at index {idx} must be non-negative integer")
        parseable = call['parseable']
        if not isinstance(parseable, bool):
            raise ValueError(f"parseable at index {idx} must be boolean")
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        tokens = call['prediction_tokens']
        parseable = call['parseable']
        gain = loss_without - loss_with
        normalized_gain = gain / max(tokens, 1)
        normalized_gain = round(normalized_gain, 10)
        accepted = parseable and normalized_gain >= threshold
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": normalized_gain
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }"}
